import pathlib,json,subprocess,hashlib,difflib,os,time,shutil
repo=pathlib.Path(r'C:/Users/Dan/Desktop/Projects/formal-pvnp'); pkg=repo/'certifications/realizable-hardness'
out=pkg/'.lake/build/independent-review-20260912'; out.mkdir(exist_ok=True)
m=json.loads((pkg/'source-map.json').read_text()); report=[]; diffs=[]
for e in m['entries']:
 b=subprocess.check_output(['git','show',e['source_commit']+':'+e['source_path']],cwd=repo); original=b
 assert hashlib.sha256(b).hexdigest()==e['source_git_lf_sha256']
 for t in e['transforms']:
  op=t['operation']
  if op=='normalize_crlf_to_lf': b=b.replace(b'\r\n',b'\n')
  elif op=='remove_utf8_bom':
   assert b.startswith(b'\xef\xbb\xbf'); b=b[3:]
  elif op=='replace_utf8_literal':
   x=t['before'].encode(); assert b.count(x)==1,(e['mirror_path'],x,b.count(x)); b=b.replace(x,t['after'].encode())
  else: raise Exception(op)
 assert b==(pkg/e['mirror_path']).read_bytes()
 assert hashlib.sha256(b).hexdigest()==e['mirror_sha256']
 report.append({'path':e['mirror_path'],'sha256':e['mirror_sha256'],'reconstruction':'PASS'})
 diffs.extend(difflib.unified_diff(original.decode('utf-8-sig').splitlines(True),b.decode().splitlines(True),fromfile=e['source_path'],tofile=e['mirror_path']))
(out/'provenance.json').write_text(json.dumps(report,indent=2)); (out/'source-diffs.txt').write_text(''.join(diffs),encoding='utf-8')
print('PASS',len(report),'strict source reconstructions; diff saved',out/'source-diffs.txt')
import re
mods={'.'.join(pathlib.PurePosixPath(e['mirror_path']).with_suffix('').parts[1:]):e['mirror_path'] for e in m['entries']}
ordered=[]; done=set()
def visit(mod):
 if mod in done:return
 done.add(mod)
 for dep in re.findall(r'^import\s+(\S+)',(pkg/mods[mod]).read_text(),re.M):
  if dep in mods:visit(dep)
 ordered.append(mod)
for mod in mods:visit(mod)
env=os.environ.copy(); env['LEAN_NUM_THREADS']='1'; env['PYTHONUTF8']='1'; env['PYTHONIOENCODING']='utf-8'
originalpath=env.get('LEAN_PATH',''); parts=originalpath.split(os.pathsep)
# Exclude author package output; dependencies remain same-version only.
parts=[p for p in parts if pathlib.Path(p).resolve()!= (pkg/'.lake/build/lib/lean').resolve() and pathlib.Path(p).resolve()!= (pkg/'.lake/build/lib').resolve()]
env['LEAN_PATH']=str(out/os.path.join('lib','lean'))+os.pathsep+os.pathsep.join(parts)
(out/'environment.json').write_text(json.dumps({'LEAN_PATH':env['LEAN_PATH'],'LEAN_NUM_THREADS':env['LEAN_NUM_THREADS'],'toolchain':subprocess.check_output(['lean','--version'],cwd=pkg,env=env,text=True).strip()},indent=2))
results=[]
for mod in ordered+['PvNP']:
 source=pkg/(mods[mod] if mod in mods else 'lean/PvNP.lean'); dest=out/'lib/lean'/pathlib.Path(*mod.split('.')).with_suffix('.olean');dest.parent.mkdir(parents=True,exist_ok=True)
 name=mod.split('.')[-1]+'-'+str(time.time_ns()); log=out/(name+'.log'); command=['lean','-o',str(dest),str(source)]
 assert shutil.disk_usage('C:/').free>=640*1024**2
 print('START',mod,flush=True)
 with log.open('wb') as f:
  p=subprocess.Popen(command,cwd=pkg,env=env,stdout=f,stderr=subprocess.STDOUT)
  while True:
   try:code=p.wait(timeout=10);break
   except subprocess.TimeoutExpired:
    if shutil.disk_usage('C:/').free<640*1024**2:
     subprocess.run(['taskkill','/PID',str(p.pid),'/T','/F'],stdout=subprocess.DEVNULL);code=p.wait();break
 row={'module':mod,'command':command,'exit_code':code,'log':str(log),'log_sha256':hashlib.sha256(log.read_bytes()).hexdigest(),'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'output':str(dest),'output_sha256':hashlib.sha256(dest.read_bytes()).hexdigest() if dest.exists() else None}
 results.append(row);(out/'results.json').write_text(json.dumps(results,indent=2))
 print('END',mod,'EXIT',code,'LOG',log,flush=True)
 if code:raise SystemExit(code)
print('ALL 34 REVIEW EXPORTS EXIT 0',flush=True)
